/**
 * Client-side export helpers for the "master bill" table exports the e-invoice procedure
 * requires (Excel/XML/PDF, from the front-end application itself — दफा ६(ठ)). PDF is covered by
 * the browser's native Print-to-PDF on the app's already-print-formatted pages (invoice detail,
 * sales book). Excel is a real .xls file (SpreadsheetML 2003 XML, opened natively by Excel/
 * LibreOffice/Google Sheets) generated by hand here rather than via the `xlsx`/SheetJS package —
 * that package's writer path is fine, but it ships known prototype-pollution/ReDoS CVEs in code
 * paths we'd otherwise be pulling into the bundle for no benefit, since our own tables are
 * trusted data we generate, not files we need to parse.
 */

function download(content: string, mimeType: string, filename: string) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

function csvCell(value: unknown): string {
  const s = value == null ? '' : String(value);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function exportCsv<T extends Record<string, unknown>>(
  rows: T[],
  columns: { key: keyof T; header: string }[],
  filename: string,
) {
  const lines = [
    columns.map((c) => csvCell(c.header)).join(','),
    ...rows.map((row) => columns.map((c) => csvCell(row[c.key])).join(',')),
  ];
  download(lines.join('\r\n'), 'text/csv;charset=utf-8', filename);
}

function xmlEscape(value: unknown): string {
  const s = value == null ? '' : String(value);
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function xlsCell(value: unknown): string {
  if (value == null) return '<Cell><Data ss:Type="String"></Data></Cell>';
  if (typeof value === 'number') return `<Cell><Data ss:Type="Number">${value}</Data></Cell>`;
  if (typeof value === 'boolean') return `<Cell><Data ss:Type="String">${value ? 'Yes' : 'No'}</Data></Cell>`;
  return `<Cell><Data ss:Type="String">${xmlEscape(value)}</Data></Cell>`;
}

export function exportExcel<T extends Record<string, unknown>>(
  rows: T[],
  columns: { key: keyof T; header: string }[],
  sheetName: string,
  filename: string,
) {
  const headerRow = `<Row>${columns.map((c) => `<Cell><Data ss:Type="String">${xmlEscape(c.header)}</Data></Cell>`).join('')}</Row>`;
  const dataRows = rows
    .map((row) => `<Row>${columns.map((c) => xlsCell(row[c.key])).join('')}</Row>`)
    .join('\n');
  const xml =
    '<?xml version="1.0"?>\n' +
    '<?mso-application progid="Excel.Sheet"?>\n' +
    '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" ' +
    'xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">\n' +
    `<Worksheet ss:Name="${xmlEscape(sheetName.slice(0, 31))}">\n<Table>\n${headerRow}\n${dataRows}\n</Table>\n</Worksheet>\n</Workbook>`;
  download(xml, 'application/vnd.ms-excel;charset=utf-8', filename);
}

export function exportXml<T extends Record<string, unknown>>(
  rows: T[],
  columns: { key: keyof T; header: string }[],
  rootTag: string,
  rowTag: string,
  filename: string,
) {
  const body = rows
    .map(
      (row) =>
        `  <${rowTag}>\n` +
        columns.map((c) => `    <${c.header}>${xmlEscape(row[c.key])}</${c.header}>`).join('\n') +
        `\n  </${rowTag}>`,
    )
    .join('\n');
  const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<${rootTag}>\n${body}\n</${rootTag}>`;
  download(xml, 'application/xml;charset=utf-8', filename);
}
